using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.OpenAI;

// Configure with DI
builder.Services.AddChatClient(sp =>
{
    var apiKey = sp.GetRequiredService<IConfiguration>()["OpenAI:ApiKey"];
    return new OpenAIClient(apiKey).AsChatClient();
});

// Use the abstraction
public class ProductService
{
    private readonly IChatClient _chatClient;

    public ProductService(IChatClient chatClient)
    {
        _chatClient = chatClient;
    }

    public async Task<string> GenerateDescriptionAsync(string productName)
    {
        var messages = new List<ChatMessage>
        {
            new ChatMessage(ChatRole.System, "You are a marketing copywriter."),
            new ChatMessage(ChatRole.User, $"Write a product description for: {productName}")
        };

        var response = await _chatClient.CompleteAsync(messages);
        return response.Message.Text;
    }
}

// Middleware for logging
public class LoggingChatClientMiddleware : IChatClientMiddleware
{
    private readonly ILogger _logger;

    public async Task<ChatCompletion> OnCompleteAsync(
        IList<ChatMessage> messages,
        ChatOptions options,
        Func<IList<ChatMessage>, ChatOptions, Task<ChatCompletion>> next,
        CancellationToken cancellationToken)
    {
        _logger.LogInformation("Generating completion for {MessageCount} messages", messages.Count);

        var stopwatch = Stopwatch.StartNew();
        var result = await next(messages, options, cancellationToken);
        stopwatch.Stop();

        _logger.LogInformation(
            "Completion generated in {ElapsedMs}ms with {TokenCount} tokens",
            stopwatch.ElapsedMilliseconds,
            result.Usage?.TotalTokenCount ?? 0);

        return result;
    }
}
